-- E&P Learning: M2 physical-science knowledge graph (ว 2.2 and ว 2.3).
-- Official Thai Basic Education curriculum B.E. 2551, revised B.E. 2560.
-- Seeds 15 force indicators and 6 energy indicators for M2 only.
-- No school or learner records are created.
begin;
do $$ begin if not exists(select 1 from public.learning_subjects s join public.learning_curricula c on c.code='TH-SCI-M1-M6' join public.learning_education_systems es on es.id=c.education_system_id join public.learning_grade_levels g on g.curriculum_id=c.id and g.code='M2' where s.code='SCI' and es.code='TH_BASIC' and s.status='active' and c.status='active' and g.status='active') then raise exception 'Active SCI M2 curriculum is required.'; end if; end $$;
insert into public.learning_topics(skill_id,code,name,description,sequence_no,status) select sk.id,t.code,t.name,t.description,t.seq,'active' from public.learning_subjects s join public.learning_skills sk on sk.subject_id=s.id join (values ('FORCE','M2-FORCES','Forces and Motion','Thai M2 Science topic aligned to standard ว 2.2.',1),('ENERGY','M2-WORK-ENERGY','Work, Power and Mechanical Energy','Thai M2 Science topic aligned to standard ว 2.3.',2)) as t(skill_code,code,name,description,seq) on true where s.code='SCI' on conflict(skill_id,code) do update set name=excluded.name,description=excluded.description,sequence_no=excluded.sequence_no,status='active',updated_at=now();
insert into public.learning_objectives(topic_id,code,name,description,sequence_no,status) select tp.id,o.code,o.name,o.description,o.seq,'active' from public.learning_subjects s join public.learning_skills sk on sk.subject_id=s.id join (values ('M2-FORCES','M2-S2_2-01','Predict motion from resultant force','Predict motion caused by the resultant of collinear forces using evidence.',1),('M2-FORCES','M2-S2_2-02','Draw collinear force diagrams','Draw force diagrams showing forces and their resultant on an object.',2),('M2-FORCES','M2-S2_2-03','Investigate liquid pressure','Design a fair investigation of factors affecting liquid pressure.',3),('M2-FORCES','M2-S2_2-04','Explain buoyancy and floating','Analyse buoyant force and why objects sink or float in liquids.',4),('M2-FORCES','M2-S2_2-05','Represent forces in a liquid','Draw a force diagram for an object in a liquid.',5),('M2-FORCES','M2-S2_2-06','Compare static and kinetic friction','Explain static and kinetic friction using evidence.',6),('M2-FORCES','M2-S2_2-07','Investigate factors affecting friction','Design an experiment to investigate factors affecting friction magnitude.',7),('M2-FORCES','M2-S2_2-08','Draw friction force diagrams','Draw diagrams showing friction and other forces acting on an object.',8),('M2-FORCES','M2-S2_2-09','Apply friction in everyday life','Explain when friction should be increased or reduced in everyday situations.',9),('M2-FORCES','M2-S2_2-10','Investigate moments of force','Investigate rotational equilibrium and calculate moment using M = F × l.',10),('M2-FORCES','M2-S2_2-11','Compare magnetic, electric and gravitational fields','Compare sources of magnetic, electric and gravitational fields and the forces they exert.',11),('M2-FORCES','M2-S2_2-12','Draw field-force diagrams','Draw diagrams showing magnetic, electric and gravitational forces on objects.',12),('M2-FORCES','M2-S2_2-13','Compare strengths of non-contact forces','Analyse factors affecting magnetic, electric and gravitational force magnitudes.',13),('M2-FORCES','M2-S2_2-14','Calculate speed and velocity','Calculate speed and velocity using distance or displacement divided by time.',14),('M2-FORCES','M2-S2_2-15','Represent displacement and velocity','Draw diagrams representing displacement and velocity.',15),('M2-WORK-ENERGY','M2-S2_3-01','Calculate work and power','Calculate work and power using W = Fs and P = W/t.',16),('M2-WORK-ENERGY','M2-S2_3-02','Explain simple machines','Analyse how simple machines change the size or direction of applied forces.',17),('M2-WORK-ENERGY','M2-S2_3-03','Apply simple machines','Explain benefits and everyday applications of simple machines.',18),('M2-WORK-ENERGY','M2-S2_3-04','Investigate kinetic and gravitational potential energy','Design an investigation of factors affecting kinetic and gravitational potential energy.',19),('M2-WORK-ENERGY','M2-S2_3-05','Explain conservation of mechanical energy','Interpret data showing transfers between gravitational potential and kinetic energy when mechanical energy is conserved.',20),('M2-WORK-ENERGY','M2-S2_3-06','Apply conservation of energy','Analyse energy transformations and transfers using the conservation of energy law.',21)) as o(topic_code,code,name,description,seq) on true join public.learning_topics tp on tp.skill_id=sk.id and tp.code=o.topic_code where s.code='SCI' on conflict(topic_id,code) do update set name=excluded.name,description=excluded.description,sequence_no=excluded.sequence_no,status='active',updated_at=now();
insert into public.learning_objective_alignments(objective_id,curriculum_id,grade_level_id,sequence_no,required,notes) select ob.id,c.id,g.id,a.seq,true,'Thailand Basic Education Core Curriculum B.E. 2551 (2008), revised B.E. 2560 (2017); official indicator '||a.indicator||'.' from (values ('M2-S2_2-01',1,'ว 2.2 ม.2/1'),('M2-S2_2-02',2,'ว 2.2 ม.2/2'),('M2-S2_2-03',3,'ว 2.2 ม.2/3'),('M2-S2_2-04',4,'ว 2.2 ม.2/4'),('M2-S2_2-05',5,'ว 2.2 ม.2/5'),('M2-S2_2-06',6,'ว 2.2 ม.2/6'),('M2-S2_2-07',7,'ว 2.2 ม.2/7'),('M2-S2_2-08',8,'ว 2.2 ม.2/8'),('M2-S2_2-09',9,'ว 2.2 ม.2/9'),('M2-S2_2-10',10,'ว 2.2 ม.2/10'),('M2-S2_2-11',11,'ว 2.2 ม.2/11'),('M2-S2_2-12',12,'ว 2.2 ม.2/12'),('M2-S2_2-13',13,'ว 2.2 ม.2/13'),('M2-S2_2-14',14,'ว 2.2 ม.2/14'),('M2-S2_2-15',15,'ว 2.2 ม.2/15'),('M2-S2_3-01',16,'ว 2.3 ม.2/1'),('M2-S2_3-02',17,'ว 2.3 ม.2/2'),('M2-S2_3-03',18,'ว 2.3 ม.2/3'),('M2-S2_3-04',19,'ว 2.3 ม.2/4'),('M2-S2_3-05',20,'ว 2.3 ม.2/5'),('M2-S2_3-06',21,'ว 2.3 ม.2/6')) as a(code,seq,indicator) join public.learning_objectives ob on ob.code=a.code join public.learning_topics tp on tp.id=ob.topic_id join public.learning_skills sk on sk.id=tp.skill_id join public.learning_subjects s on s.id=sk.subject_id and s.code='SCI' join public.learning_curricula c on c.code='TH-SCI-M1-M6' join public.learning_grade_levels g on g.curriculum_id=c.id and g.code='M2' on conflict(objective_id,curriculum_id,grade_level_id) do update set sequence_no=excluded.sequence_no,required=excluded.required,notes=excluded.notes,updated_at=now();
commit;
